// Testbench for fpga_m7_ar_overlay_axi (D, 2026-10-11).
// Case parameters and expected (status, FNV-1a) come from the committed
// tb_ar_overlay_vectors.h, generated by the independent numpy golden
// (tools/ar_display/golden.py; command in the header). Inputs are rebuilt
// here from the same simple formulas the golden uses:
//   depth(x,y) = (x*37 + y*101 + seed*7919 + (x*y) % 13) % 11000
//   grid[(z*32+y)*32+x] = (x*7 + z*3 + y + seed) % 4
// FNV-1a 32 over the fb as little-endian bytes (width*height pixels; none
// for status 1), then the status as 4 little-endian bytes.
// Default runs case 0 only (64x48, the co-simulation case); AR_TB_ALL=1 runs
// every case (C simulation only).
#include <cstdio>
#include <cstdlib>
#include "../../ar_overlay.hpp"
#include "tb_ar_overlay_vectors.h"

extern "C" std::uint32_t fpga_m7_ar_overlay_axi(
    const fpga_m7_ar_word*, const fpga_m7_ar_word*, const fpga_m7_ar_word*,
    fpga_m7_ar_word*, std::uint32_t, std::uint32_t, std::uint32_t,
    std::uint32_t, std::uint32_t, std::uint32_t, std::uint32_t, std::uint32_t,
    std::uint32_t, std::uint32_t, std::uint32_t, std::uint32_t, std::uint32_t,
    std::uint32_t, std::uint32_t, bool, std::uint32_t, std::uint32_t,
    std::int32_t, std::int32_t, std::uint32_t, std::uint32_t, std::uint32_t,
    std::uint32_t);

static fpga_m7_ar_word g_depth[FPGA_M7_AR_DEPTH_WORDS_MAX];
static fpga_m7_ar_word g_grid[FPGA_M7_AR_GRID_WORDS];
static fpga_m7_ar_word g_boxes[FPGA_M7_AR_DESC_WORDS];
static fpga_m7_ar_word g_fb[FPGA_M7_AR_FB_WORDS_MAX];

static void fnv(std::uint32_t& h, std::uint32_t v) {
    for (int k = 0; k < 4; ++k) { h ^= (v >> (8 * k)) & 0xFF; h *= 16777619u; }
}

static int run(const ArTbCase& c) {
    const std::uint32_t* r = c.regs;
    const std::uint32_t W = r[0], H = r[1], Wd = r[2], Hd = r[3];
    const std::uint64_t dpx = static_cast<std::uint64_t>(Wd) * Hd;
    for (std::uint32_t i = 0; i < FPGA_M7_AR_DEPTH_WORDS_MAX; ++i) g_depth[i] = 0;
    for (std::uint64_t i = 0; i < dpx && i < 8ull * FPGA_M7_AR_DEPTH_WORDS_MAX; ++i) {
        const std::uint32_t x = i % Wd, y = i / Wd;
        const std::uint32_t z = (x * 37 + y * 101 + c.seed * 7919 + (x * y) % 13) % 11000;
        g_depth[i / 8].range(16 * (i % 8) + 15, 16 * (i % 8)) = z;
    }
    for (std::uint32_t i = 0; i < 32768u; ++i) {
        const std::uint32_t x = i % 32, y = (i / 32) % 32, z = i / 1024;
        g_grid[i / 16].range(8 * (i % 16) + 7, 8 * (i % 16)) = (x * 7 + z * 3 + y + c.seed) % 4;
    }
    std::uint32_t desc[FPGA_M7_AR_DESC_U32] = {0};
    desc[0] = c.magic;
    desc[1] = c.count;
    for (std::uint32_t b = 0; b < c.n_rows; ++b)
        for (std::uint32_t k = 0; k < 6; ++k) desc[2 + 6 * b + k] = c.rows[b][k];
    for (std::uint32_t i = 0; i < FPGA_M7_AR_DESC_U32; ++i)
        g_boxes[i / 4].range(32 * (i % 4) + 31, 32 * (i % 4)) = desc[i];
    for (std::uint32_t i = 0; i < FPGA_M7_AR_FB_WORDS_MAX; ++i)
        for (int j = 0; j < 4; ++j) g_fb[i].range(32 * j + 31, 32 * j) = 0xDEADBEEFu;

    const std::uint32_t st = fpga_m7_ar_overlay_axi(
        g_depth, g_grid, g_boxes, g_fb, r[0], r[1], r[2], r[3], r[4], r[5],
        r[6], r[7], r[8], r[9], r[10], r[11], r[12], r[13], r[14], r[15] != 0,
        r[16], r[17], static_cast<std::int32_t>(r[18]),
        static_cast<std::int32_t>(r[19]), r[20], r[21], r[22], r[23]);

    std::uint32_t h = 2166136261u;
    const std::uint32_t npx = st == 1 ? 0 : W * H;
    for (std::uint32_t i = 0; i < npx; ++i)
        fnv(h, g_fb[i / 4].range(32 * (i % 4) + 31, 32 * (i % 4)).to_uint());
    fnv(h, st);
    // Sentinel: 4 beats past the image (all beats for status 1) untouched.
    const std::uint32_t first = npx / 4;
    const std::uint32_t last = st == 1 ? FPGA_M7_AR_FB_WORDS_MAX : first + 4;
    std::uint32_t overrun = 0, leftover = 0;
    for (std::uint32_t i = first; i < last && i < FPGA_M7_AR_FB_WORDS_MAX; ++i)
        for (int j = 0; j < 4; ++j)
            overrun += g_fb[i].range(32 * j + 31, 32 * j) != 0xDEADBEEFu;
    for (std::uint32_t i = 0; i < npx; ++i)
        leftover += g_fb[i / 4].range(32 * (i % 4) + 31, 32 * (i % 4)) == 0xDEADBEEFu;
    const bool ok = st == c.expect_status && h == c.expect_hash &&
                    overrun == 0 && leftover == 0;
    std::printf("[%s] status=%u (exp %u) fnv=%08x (exp %08x) overrun=%u leftover=%u %s\n",
                c.name, st, c.expect_status, h, c.expect_hash, overrun, leftover,
                ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}

int main() {
    const char* all = std::getenv("AR_TB_ALL");
    const std::uint32_t n = (all && all[0] == '1') ? kArTbCaseCount : 1;
    int fails = 0;
    for (std::uint32_t i = 0; i < n; ++i) fails += run(kArTbCases[i]);
    std::printf("AR_TB %s cases=%u fails=%d\n", fails ? "FAIL" : "PASS", n, fails);
    return fails ? 1 : 0;
}
